function percentile(values: Float64Array, q: number): number {
  const n = values.length;
  if (n === 0) return 0;
  const sorted = Float64Array.from(values).sort();
  const pos = (q / 100) * (n - 1);
  const lo = Math.floor(pos);
  const hi = Math.min(n - 1, Math.ceil(pos));
  const w = pos - lo;
  return sorted[lo] * (1 - w) + sorted[hi] * w;
}

function resizeBilinear2D(
  src: Float64Array,
  sh: number,
  sw: number,
  dstH = 24,
  dstW = 16
): Float64Array {
  const out = new Float64Array(dstH * dstW);
  if (sh === 0 || sw === 0) return out;

  for (let dy = 0; dy < dstH; dy++) {
    const yIdx = Math.max(0, Math.min(sh - 1, ((dy + 0.5) * sh) / dstH - 0.5));
    const y0 = Math.floor(yIdx);
    const y1 = Math.min(y0 + 1, sh - 1);
    const wy = yIdx - y0;

    for (let dx = 0; dx < dstW; dx++) {
      const xIdx = Math.max(0, Math.min(sw - 1, ((dx + 0.5) * sw) / dstW - 0.5));
      const x0 = Math.floor(xIdx);
      const x1 = Math.min(x0 + 1, sw - 1);
      const wx = xIdx - x0;

      const top = src[y0 * sw + x0] * (1 - wx) + src[y0 * sw + x1] * wx;
      const bot = src[y1 * sw + x0] * (1 - wx) + src[y1 * sw + x1] * wx;
      out[dy * dstW + dx] = top * (1 - wy) + bot * wy;
    }
  }
  return out;
}

function splitSegments(
  mask: Uint8Array,
  h: number,
  w: number,
  totalH: number
): [number, number][] {
  const raw: [number, number][] = [];
  let inC = false;
  let start = 0;

  for (let x = 0; x < w; x++) {
    let has = false;
    for (let y = 0; y < h; y++) {
      if (mask[y * w + x]) {
        has = true;
        break;
      }
    }
    if (has && !inC) {
      start = x;
      inC = true;
    } else if (!has && inC) {
      raw.push([start, x]);
      inC = false;
    }
  }
  if (inC) {
    raw.push([start, w]);
  }

  const finalSegs: [number, number][] = [];
  while (raw.length > 0) {
    const seg = raw.shift()!;
    const s = seg[0];
    const e = seg[1];
    const segW = e - s;

    if (segW >= totalH * 0.85) {
      const colProfile = new Int32Array(segW);
      for (let x = 0; x < segW; x++) {
        let sum = 0;
        for (let y = 0; y < h; y++) {
          sum += mask[y * w + (s + x)];
        }
        colProfile[x] = sum;
      }
      let lo = Math.max(2, Math.round(totalH * 0.35));
      let hi = Math.min(segW - 2, Math.round(totalH * 0.72));
      if (hi <= lo) {
        lo = Math.max(2, Math.floor(segW * 0.25));
        hi = Math.max(lo + 1, segW - lo);
      }
      let minVal = Infinity;
      let minIdx = lo;
      for (let i = lo; i < hi; i++) {
        if (colProfile[i] < minVal) {
          minVal = colProfile[i];
          minIdx = i;
        }
      }
      raw.unshift([s + minIdx + 1, e]);
      raw.unshift([s, s + minIdx]);
      continue;
    }
    finalSegs.push([s, e]);
  }

  return finalSegs;
}

function recognizeCell(
  rgba: Uint8ClampedArray,
  imgW: number,
  yStart: number,
  yEnd: number,
  xStart: number,
  xEnd: number
): string {
  const h = yEnd - yStart;
  const w = xEnd - xStart;
  if (h < 4 || w < 4) return '';

  const lum = new Float64Array(h * w);
  for (let y = 0; y < h; y++) {
    const rowOff = (yStart + y) * imgW;
    for (let x = 0; x < w; x++) {
      const idx = (rowOff + (xStart + x)) * 4;
      lum[y * w + x] = 0.299 * rgba[idx] + 0.587 * rgba[idx + 1] + 0.114 * rgba[idx + 2];
    }
  }

  const bg = percentile(lum, 15);
  const sig = new Float64Array(h * w);
  for (let i = 0; i < lum.length; i++) {
    sig[i] = Math.max(0, lum[i] - bg);
  }

  const peak = percentile(sig, 99);
  if (peak < 20) return '';

  const th = 0.45 * peak;
  let ryMin = h;
  let ryMax = -1;
  for (let y = 0; y < h; y++) {
    let rowHas = false;
    for (let x = 0; x < w; x++) {
      if (sig[y * w + x] > th) {
        rowHas = true;
        break;
      }
    }
    if (rowHas) {
      if (y < ryMin) ryMin = y;
      if (y > ryMax) ryMax = y;
    }
  }

  if (ryMax < ryMin) return '';
  const totalH = ryMax - ryMin + 1;
  if (totalH < 5) return '';

  const mask = new Uint8Array(totalH * w);
  const sigCrop = new Float64Array(totalH * w);
  for (let y = 0; y < totalH; y++) {
    for (let x = 0; x < w; x++) {
      const v = sig[(ryMin + y) * w + x];
      mask[y * w + x] = v > th ? 1 : 0;
      sigCrop[y * w + x] = Math.min(1, Math.max(0, v / (peak + 1e-6)));
    }
  }

  const chars = splitSegments(mask, totalH, w, totalH);
  let out = '';

  for (const [cx0, cx1] of chars) {
    if (cx1 <= cx0) continue;
    const cw = cx1 - cx0;
    let cyMin = totalH;
    let cyMax = -1;

    for (let y = 0; y < totalH; y++) {
      for (let x = cx0; x < cx1; x++) {
        if (mask[y * w + x]) {
          if (y < cyMin) cyMin = y;
          if (y > cyMax) cyMax = y;
        }
      }
    }
    if (cyMax < cyMin) continue;
    const ch = cyMax - cyMin + 1;

    if (ch <= totalH * 0.45 && cyMin >= totalH * 0.45) {
      out += '.';
      continue;
    }
    if (ch < totalH * 0.5) {
      continue;
    }

    const csig = new Float64Array(ch * cw);
    for (let y = 0; y < ch; y++) {
      for (let x = 0; x < cw; x++) {
        csig[y * cw + x] = sigCrop[(cyMin + y) * w + (cx0 + x)];
      }
    }

    const patch01 = resizeBilinear2D(csig, ch, cw, 24, 16);
    let mean = 0;
    for (let i = 0; i < patch01.length; i++) mean += patch01[i];
    mean /= patch01.length;

    let variance = 0;
    for (let i = 0; i < patch01.length; i++) {
      const diff = patch01[i] - mean;
      variance += diff * diff;
    }
    const std = Math.sqrt(variance / patch01.length) + 1e-6;

    const patch = new Float64Array(patch01.length);
    for (let i = 0; i < patch01.length; i++) {
      patch[i] = (patch01[i] - mean) / std;
    }

    const scores: Record<string, number> = {};
    let bestD = '?';
    let bestScore = -1e9;

    for (const [d, tlist] of Object.entries(DIGIT_TEMPLATES)) {
      if (d === '1' && cw > ch * 0.52) continue;
      if (d !== '1' && cw <= ch * 0.35) continue;

      let maxTScore = -1e9;
      for (const t of tlist) {
        let sum = 0;
        for (let i = 0; i < 384; i++) {
          sum += patch[i] * (t[i] / 64.0);
        }
        const sc = sum / 384;
        if (sc > maxTScore) maxTScore = sc;
      }
      scores[d] = maxTScore;
      if (maxTScore > bestScore) {
        bestScore = maxTScore;
        bestD = d;
      }
    }

    if (ch >= 14 && (bestD === '6' || bestD === '8') && '6' in scores && '8' in scores) {
      const r0 = Math.floor(ch * 0.25);
      const r1 = Math.max(r0 + 1, Math.floor(ch * 0.48));
      const c0 = Math.floor(cw * 0.5);
      let minRight = 1.0;
      for (let y = r0; y < r1; y++) {
        let rSum = 0;
        const rCount = Math.max(1, cw - c0);
        for (let x = c0; x < cw; x++) {
          rSum += mask[(cyMin + y) * w + (cx0 + x)];
        }
        const rAvg = rSum / rCount;
        if (rAvg < minRight) minRight = rAvg;
      }
      bestD = minRight < 0.25 ? '6' : '8';
    }

    out += bestD;
  }

  return out;
}

function refineGridConsensus(grid: string[][]): string[][] {
  if (!grid || grid.length !== 6) return grid;
  const nCols = grid[0]?.length || 0;
  if (nCols < 2) return grid;

  const out = grid.map(r => [...r]);
  for (let r1 = 0; r1 < 6; r1++) {
    const matchingRows = [r1];
    for (let r2 = 0; r2 < 6; r2++) {
      if (r1 === r2) continue;
      let same = 0;
      for (let c = 0; c < nCols; c++) {
        if (grid[r1][c] !== '' && grid[r1][c] === grid[r2][c]) {
          same++;
        }
      }
      if (same >= Math.max(2, nCols - 1)) {
        matchingRows.push(r2);
      }
    }
    if (matchingRows.length >= 2) {
      for (let c = 0; c < nCols; c++) {
        const counts: Record<string, number> = {};
        for (const r of matchingRows) {
          const v = grid[r][c];
          if (v !== '') counts[v] = (counts[v] || 0) + 1;
        }
        let bestV = out[r1][c];
        let bestCount = 0;
        for (const [v, cnt] of Object.entries(counts)) {
          if (
            cnt > bestCount ||
            (cnt === bestCount && v.includes('.') && !bestV.includes('.'))
          ) {
            bestCount = cnt;
            bestV = v;
          }
        }
        if (bestCount >= 2) {
          out[r1][c] = bestV;
        }
      }
    }
  }
  return out;
}

export function scanDamageTableFromRGBA(
  rgba: Uint8ClampedArray,
  W: number,
  H: number
): ScanResult | null {
  if (W < 40 || H < 40) return null;

  // 6 hue bands: Head (Red), Chest (Orange), Stomach (Yellow), Upper Arm (Green), Lower Arm (Cyan), Leg (Purple)
  const masks = Array.from({ length: 6 }, () => new Uint8Array(H * W));
  const colCounts = Array.from({ length: 6 }, () => new Int32Array(W));

  for (let y = 0; y < H; y++) {
    const rowOff = y * W;
    for (let x = 0; x < W; x++) {
      const p = rowOff + x;
      const idx = p * 4;
      const r = rgba[idx];
      const g = rgba[idx + 1];
      const b = rgba[idx + 2];

      const mx = Math.max(r, g, b);
      const mn = Math.min(r, g, b);
      const c = mx - mn;

      if (c <= 22 || mx <= 95 || mn >= 165) continue;

      let h = 0;
      if (mx === r) {
        h = (60 * ((g - b) / (c + 1e-6))) % 360;
        if (h < 0) h += 360;
      } else if (mx === g) {
        h = 60 * ((b - r) / (c + 1e-6)) + 120;
      } else {
        h = 60 * ((r - g) / (c + 1e-6)) + 240;
      }

      let band = -1;
      if (h >= 330 || h < 18) band = 0;
      else if (h >= 18 && h < 48) band = 1;
      else if (h >= 48 && h < 80) band = 2;
      else if (h >= 80 && h < 155) band = 3;
      else if (h >= 155 && h < 215) band = 4;
      else if (h >= 215 && h < 310) band = 5;

      if (band >= 0) {
        masks[band][p] = 1;
        colCounts[band][x]++;
      }
    }
  }

  const maxSingleLimit = Math.max(18, H * 0.14);
  const textCols = new Uint8Array(W);
  for (let x = 0; x < W; x++) {
    let maxC = 0;
    for (let b = 0; b < 6; b++) {
      if (colCounts[b][x] > maxC) maxC = colCounts[b][x];
    }
    textCols[x] = maxC < maxSingleLimit ? 1 : 0;
  }

  const win = Math.max(5, Math.floor(H / 40));
  const halfWin = Math.floor(win / 2);
  const smooth = Array.from({ length: 6 }, () => new Float64Array(H));

  for (let b = 0; b < 6; b++) {
    const profile = new Int32Array(H);
    for (let y = 0; y < H; y++) {
      const rowOff = y * W;
      let sum = 0;
      for (let x = 0; x < W; x++) {
        if (textCols[x] && masks[b][rowOff + x]) sum++;
      }
      profile[y] = sum;
    }
    for (let y = 0; y < H; y++) {
      let s = 0;
      for (let k = -halfWin; k < -halfWin + win; k++) {
        const yy = y + k;
        if (yy >= 0 && yy < H) s += profile[yy];
      }
      smooth[b][y] = s;
    }
  }

  let bestScore = -1;
  let bestY0 = 0;
  let bestStep = 0;
  const minStep = Math.max(8, Math.floor(H * 0.035));
  const maxStep = Math.min(Math.floor(H * 0.22), Math.floor((H - 2) / 5));

  for (let step = minStep; step <= maxStep; step++) {
    const maxY0 = H - 5 * step - 1;
    if (maxY0 <= 0) continue;
    for (let y0 = 0; y0 < maxY0; y0++) {
      let valid = true;
      let score = 0;
      for (let r = 0; r < 6; r++) {
        const v = smooth[r][y0 + r * step];
        if (v < 6) {
          valid = false;
          break;
        }
        score += Math.log1p(v);
      }
      if (valid && score > bestScore) {
        bestScore = score;
        bestY0 = y0;
        bestStep = step;
      }
    }
  }

  if (bestScore < 0 || bestStep === 0) return null;

  const rowCenters = Array.from({ length: 6 }, (_, r) => bestY0 + r * bestStep);
  const halfH = Math.max(5, Math.floor(bestStep * 0.25));
  const combinedX = new Int32Array(W);

  for (let r = 0; r < 6; r++) {
    const yc = rowCenters[r];
    const y0 = Math.max(0, yc - halfH);
    const y1 = Math.min(H, yc + halfH + 1);
    for (let y = y0; y < y1; y++) {
      const rowOff = y * W;
      for (let x = 0; x < W; x++) {
        if (textCols[x] && masks[r][rowOff + x]) {
          combinedX[x]++;
        }
      }
    }
  }

  const gapTol = Math.max(4, Math.floor(bestStep * 0.22));
  const segs: [number, number][] = [];
  let inSeg = false;
  let segStart = 0;
  let gap = 0;

  for (let x = 0; x < W; x++) {
    if (combinedX[x] >= 2) {
      if (!inSeg) {
        segStart = x;
        inSeg = true;
      }
      gap = 0;
    } else if (inSeg) {
      gap++;
      if (gap > gapTol) {
        segs.push([segStart, x - gap]);
        inSeg = false;
      }
    }
  }
  if (inSeg) {
    segs.push([segStart, W]);
  }

  const validCols: [number, number][] = [];
  const pad = Math.max(4, Math.floor(bestStep * 0.16));

  for (const [x0, x1] of segs) {
    if (x1 - x0 < 4) continue;
    let rowsPresent = 0;
    for (let r = 0; r < 6; r++) {
      const yc = rowCenters[r];
      const y0 = Math.max(0, yc - halfH);
      const y1 = Math.min(H, yc + halfH + 1);
      let count = 0;
      for (let y = y0; y < y1; y++) {
        const rowOff = y * W;
        for (let x = x0; x < x1; x++) {
          count += masks[r][rowOff + x];
        }
      }
      if (count >= 3) rowsPresent++;
    }
    if (rowsPresent >= 4) {
      validCols.push([Math.max(0, x0 - pad), Math.min(W, x1 + pad)]);
    }
  }

  if (validCols.length === 0) return null;

  let grid: string[][] = [];
  for (let r = 0; r < 6; r++) {
    const yc = rowCenters[r];
    const y0 = Math.max(0, yc - halfH);
    const y1 = Math.min(H, yc + halfH + 1);
    const rowVals = validCols.map(([x0, x1]) => recognizeCell(rgba, W, y0, y1, x0, x1));
    grid.push(rowVals);
  }

  grid = refineGridConsensus(grid);

  const boundaries: string[] = [];
  const ryc = Math.round(rowCenters[5] + 1.56 * bestStep);
  const ry0 = Math.max(0, ryc - halfH);
  const ry1 = Math.min(H, ryc + halfH + 1);
  const rx0 = Math.max(0, validCols[0][0] - Math.floor(bestStep * 1.5));
  const rx1 = Math.min(W, validCols[validCols.length - 1][1] + Math.floor(bestStep * 1.5));

  if (ry1 - ry0 >= 5 && ryc < H && rx1 > rx0) {
    const sh = ry1 - ry0;
    const sw = rx1 - rx0;
    const stripLum = new Float64Array(sh * sw);
    for (let y = 0; y < sh; y++) {
      const rowOff = (ry0 + y) * W;
      for (let x = 0; x < sw; x++) {
        const idx = (rowOff + (rx0 + x)) * 4;
        stripLum[y * sw + x] = 0.299 * rgba[idx] + 0.587 * rgba[idx + 1] + 0.114 * rgba[idx + 2];
      }
    }
    const bg = percentile(stripLum, 20);
    const stripSig = new Float64Array(sh * sw);
    for (let i = 0; i < stripLum.length; i++) {
      stripSig[i] = Math.max(0, stripLum[i] - bg);
    }
    const peak = percentile(stripSig, 99);
    if (peak > 30) {
      const rth = 0.42 * peak;
      const rgapTol = Math.max(3, Math.floor(bestStep * 0.18));
      const rsegs: [number, number][] = [];
      let inRs = false;
      let rsStart = 0;
      let rgap = 0;

      for (let x = 0; x < sw; x++) {
        let colHas = false;
        for (let y = 0; y < sh; y++) {
          if (stripSig[y * sw + x] > rth) {
            colHas = true;
            break;
          }
        }
        if (colHas) {
          if (!inRs) {
            rsStart = x;
            inRs = true;
          }
          rgap = 0;
        } else if (inRs) {
          rgap++;
          if (rgap > rgapTol) {
            rsegs.push([rsStart, x - rgap + 1]);
            inRs = false;
          }
        }
      }
      if (inRs) {
        rsegs.push([rsStart, sw]);
      }

      const rpad = Math.max(8, Math.floor(bestStep * 0.35));
      for (const [sx0, sx1] of rsegs) {
        const cellX0 = rx0 + Math.max(0, sx0 - rpad);
        const cellX1 = rx0 + Math.min(sw, sx1 + rpad);
        const val = recognizeCell(rgba, W, ry0, ry1, cellX0, cellX1);
        if (val && /^\d+(\.\d+)?$/.test(val)) {
          boundaries.push(val);
        }
      }
    }
  }

  const numRanges = validCols.length;
  const ranges: ExtractedRange[] = [];

  for (let c = 0; c < numRanges; c++) {
    const damages: Record<PartId, string> = {
      head: grid[0][c] || '',
      chest: grid[1][c] || '',
      stomach: grid[2][c] || '',
      upper_arm: grid[3][c] || '',
      lower_arm: grid[4][c] || '',
      leg: grid[5][c] || '',
    };
    const hasAtLeastFour = Object.values(damages).filter(v => v !== '' && !isNaN(parseFloat(v))).length >= 4;
    if (!hasAtLeastFour) continue;

    const from = boundaries.length >= c + 2 ? boundaries[c] : undefined;
    const to = boundaries.length >= c + 2 ? boundaries[c + 1] : undefined;
    ranges.push({
      rangeIndex: ranges.length + 1,
      from,
      to,
      damages,
    });
  }

  if (ranges.length === 0) return null;
  return { ranges, boundaries };
}

export async function scanDamageImageFile(source: File | Blob | string): Promise<ScanResult | null> {
  return new Promise((resolve) => {
    const img = new Image();
    let objectUrl: string | null = null;

    const cleanup = () => {
      if (objectUrl) {
        URL.revokeObjectURL(objectUrl);
      }
    };

    img.onload = () => {
      cleanup();
      try {
        const w = img.naturalWidth || img.width;
        const h = img.naturalHeight || img.height;
        const canvas = document.createElement('canvas');
        canvas.width = w;
        canvas.height = h;
        const ctx = canvas.getContext('2d');
        if (!ctx) {
          resolve(null);
          return;
        }
        ctx.drawImage(img, 0, 0, w, h);
        const imageData = ctx.getImageData(0, 0, w, h);
        const res = scanDamageTableFromRGBA(imageData.data, w, h);
        resolve(res);
      } catch {
        resolve(null);
      }
    };

    img.onerror = () => {
      cleanup();
      resolve(null);
    };

    if (typeof source === 'string') {
      img.src = source;
    } else {
      objectUrl = URL.createObjectURL(source);
      img.src = objectUrl;
    }
  });
}
